// ── Clean the teams array to remove any accidental duplicates introduced
// during inline construction — the filter above handles runtime safety,
// but we also export a cleaned reference for consumers.
export const cleanedTeams: TeamProjection[] = (() => {
  const seen = new Set<string>();
  return projectionsData.teams.filter((t) => {
    if (seen.has(t.team)) return false;
    seen.add(t.team);
    return true;
  });
})();